package com.rezoxnemesis.videostudio;
import android.graphics.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import java.io.*;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;
import static org.junit.Assert.*;
/** Real native guide transmission; synthetic folds do not certify actor likeness. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class LocalDrawingStructureEdgesTest {
 static JSONObject edges(int low,int high)throws Exception{return new JSONObject().put("low",low).put("high",high);}
 static Bitmap custom(Bitmap source,JSONObject settings)throws Exception{Method method;try{method=LocalDrawingPairedSource.class.getDeclaredMethod("canny",Bitmap.class,JSONObject.class);}catch(NoSuchMethodException missing){throw new AssertionError("Shared native Canny must accept explicit bounded edge thresholds",missing);}method.setAccessible(true);try{return(Bitmap)method.invoke(null,source,settings);}catch(InvocationTargetException cause){if(cause.getCause()instanceof Exception)throw(Exception)cause.getCause();throw cause;}}
 static Bitmap earFold(){Bitmap image=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(Color.WHITE);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setStyle(Paint.Style.STROKE);p.setColor(Color.BLACK);p.setStrokeWidth(3);canvas.drawOval(new RectF(140,85,365,430),p);p.setColor(Color.rgb(160,160,160));p.setStrokeWidth(1.2f);Path fold=new Path();fold.moveTo(270,155);fold.cubicTo(210,135,185,220,238,253);fold.cubicTo(290,284,205,320,255,355);canvas.drawPath(fold,p);return image;}
 static int interior(Bitmap b){int n=0;for(int y=150;y<360;y++)for(int x=190;x<310;x++){int c=b.getPixel(x,y);assertTrue("Native structure remains binary opaque",c==Color.BLACK||c==Color.WHITE);if(c==Color.WHITE)n++;}return n;}
 static void evidence(String name,Bitmap b)throws Exception{String location=System.getenv("VIDEOSTUDIO_STRUCTURE_EDGE_EVIDENCE");if(location==null)return;File dir=new File(location);assertTrue(dir.mkdirs()||dir.isDirectory());File out=new File(dir,name);assertFalse("Preserve each native threshold trial",out.exists());try(FileOutputStream stream=new FileOutputStream(out)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,stream));}System.out.println(name+" SHA256 "+SketchProjectStore.fileHash(out));}
 @Test public void lowerExplicitThresholdsTransmitTheExistingFaintEarFoldWithoutInventingInk()throws Exception{Bitmap input=earFold(),old=LocalDrawingPairedSource.canny(input),fine=null;try{evidence("synthetic-ear-source.png",input);evidence("legacy-100-200.png",old);assertEquals("The faint internal fold must reproduce the observed old detail loss",0,interior(old));fine=custom(input,edges(20,50));evidence("explicit-20-50.png",fine);assertTrue("Lower thresholds must retain actual authored interior fold pixels",interior(fine)>180);assertEquals(Color.BLACK,fine.getPixel(50,50));assertEquals(Color.BLACK,fine.getPixel(450,450));}finally{input.recycle();old.recycle();if(fine!=null)fine.recycle();}}
 @Test public void explicitHistoricalThresholdsArePixelExactWithTheUnchangedOmittedKernel()throws Exception{Bitmap input=earFold(),old=LocalDrawingPairedSource.canny(input),explicit=null;try{explicit=custom(input,edges(100,200));assertTrue("Explicit old thresholds must retain every original binary native pixel",old.sameAs(explicit));}finally{input.recycle();old.recycle();if(explicit!=null)explicit.recycle();}}
 @Test public void omittedThresholdsPreserveTheHistoricalPairedWireFingerprint()throws Exception{JSONObject p=new JSONObject("{\"appearanceSource\":{\"objectId\":\"guide\",\"sourceSha256\":\""+"c".repeat(64)+"\"},\"conditioning\":{\"appearanceStrength\":0.7,\"structureStrength\":0.9},\"expectedRevision\":2,\"frameSource\":{\"documentSha256\":\""+"a".repeat(64)+"\",\"frameIndex\":0,\"layerIds\":[\"layer_1\"]},\"requestId\":\"legacy\",\"settings\":{\"guidance\":7,\"prompt\":\"Precise graphite portrait\",\"seed\":41718,\"steps\":24,\"strength\":0.5},\"sketchId\":\"source\"}");String before=SketchDocument.canonical(p);LocalDrawingSource.validate(p);assertEquals(before,SketchDocument.canonical(p));assertEquals("18fc5f057f952c0e02d8b884cdcebc31bf178e9cc4353ebf455ce46d4ba32e0d",LocalDrawingRequestIdentity.fingerprint("b".repeat(64),p));assertFalse(p.getJSONObject("conditioning").has("structureEdges"));}
 @Test public void nativeThresholdAdmissionIsStrictAndBoundedBeforeAnyStudy()throws Exception{LocalDrawingPairedSourceTest f=new LocalDrawingPairedSourceTest();f.fixture();for(JSONObject good:new JSONObject[]{edges(1,1020),edges(20,50),edges(100,200)}){JSONObject p=SketchDocument.copy(f.request);p.getJSONObject("conditioning").put("structureEdges",good);LocalDrawingSource.validate(p);}for(Object bad:new Object[]{JSONObject.NULL,true,1,"20,50",new JSONArray(),new JSONObject(),new JSONObject().put("low",20),new JSONObject().put("low","20").put("high",50),new JSONObject().put("low",20).put("high",50.5),new JSONObject().put("low",20).put("high",50).put("automatic",true),edges(0,50),edges(20,1021),edges(50,50),edges(200,100)}){JSONObject p=SketchDocument.copy(f.request);p.getJSONObject("conditioning").put("structureEdges",bad);assertThrows(String.valueOf(bad),Exception.class,()->LocalDrawingSource.validate(p));}assertFalse(new File(f.context.getFilesDir(),"local_drawing/studies").exists());}
 @Test public void nativePreviewAndFrozenRetryBindThresholdsWithoutChangingSourceOrAppearance()throws Exception{LocalDrawingPairedSourceTest f=new LocalDrawingPairedSourceTest();f.fixture();JSONObject p=SketchDocument.copy(f.request),old=f.execute(SketchDocument.copy(p).put("previewOnly",true));String before=SketchDocument.canonical(f.frame.document());p.getJSONObject("conditioning").put("structureEdges",edges(20,50));JSONObject preview=f.execute(SketchDocument.copy(p).put("previewOnly",true));assertEquals(old.getJSONObject("localDrawingSourcePreviewImage").getString("sha256"),preview.getJSONObject("localDrawingSourcePreviewImage").getString("sha256"));assertEquals(old.getJSONObject("localDrawingAppearancePreviewImage").getString("sha256"),preview.getJSONObject("localDrawingAppearancePreviewImage").getString("sha256"));assertFalse(old.has("structureEdgeThresholds"));assertEquals(edges(20,50).toString(),preview.getJSONObject("structureEdgeThresholds").toString());assertFalse(new File(f.context.getFilesDir(),"local_drawing/studies").exists());Exception absent=assertThrows(Exception.class,()->f.execute(p));assertTrue(absent.toString(),absent.toString().contains("MODEL_NOT_INSTALLED"));JSONObject receipt=LocalDrawingOperations.execute(f.context,"local_drawing_get",new JSONObject().put("requestId",p.getString("requestId")),null);assertEquals(edges(20,50).toString(),receipt.getJSONObject("structureEdgeThresholds").toString());assertEquals(preview.getJSONObject("localDrawingStructurePreviewImage").getString("sha256"),receipt.getString("preparedStructureSha256"));assertTrue(assertThrows(Exception.class,()->f.execute(SketchDocument.copy(p))).toString().contains("MODEL_NOT_INSTALLED"));JSONObject changed=SketchDocument.copy(p);changed.getJSONObject("conditioning").getJSONObject("structureEdges").put("low",21);assertTrue(assertThrows(Exception.class,()->f.execute(changed)).toString().contains("REQUEST_ID_CONFLICT"));assertEquals(before,SketchDocument.canonical(f.frame.document()));}
 @Test public void interruptedEdgePreparationCancelsBeforePublishingAnyNewOutput()throws Exception{Bitmap input=earFold();Thread.currentThread().interrupt();try{assertThrows(InterruptedException.class,()->custom(input,edges(20,50)));}finally{Thread.interrupted();input.recycle();}}
 static LocalDrawingPairedKeyframeTest completed()throws Exception{LocalDrawingPairedKeyframeTest p=new LocalDrawingPairedKeyframeTest();p.pairedReceipt();JSONObject request=p.fixture.record.getJSONObject("request");request.getJSONObject("conditioning").put("structureEdges",edges(20,50));p.fixture.record.put("requestSha256",LocalDrawingRequestIdentity.fingerprint(p.fixture.record.getString("modelIdentity"),request));p.fixture.saveRecord();return p;}
 @Test public void explicitThresholdRecipeSurvivesUndoAndArchiveButTamperingRejects()throws Exception{LocalDrawingPairedKeyframeTest p=completed();p.fixture.chosenDraftBecomesOnlyItsExplicitCelAndRetainsProvenanceThroughUndoAndArchive();JSONObject d=p.fixture.document(),request=SketchDocument.object(d,"ai_key").getJSONObject("reference").getJSONObject("localDrawing").getJSONObject("request");assertEquals(20,request.getJSONObject("conditioning").getJSONObject("structureEdges").getInt("low"));request.getJSONObject("conditioning").getJSONObject("structureEdges").put("low",21);assertThrows(Exception.class,()->SketchDocument.validate(d));}
 @Test public void explicitThresholdRecipeSurvivesCharacterComponentReuse()throws Exception{completed().fixture.characterLibraryReusesTheKeyWithProvenanceAndAnExplicitExposure();}
}
